from functools import wraps
from flask import Flask, request, abort

app = Flask(__name__)
ROLES = {"alice": "admin", "bob": "viewer"}
USERS = ["alice", "bob"]

def require_role(role):
    def deco(fn):
        @wraps(fn)
        def wrapper(user, *a, **k):
            if ROLES.get(user) != role:
                abort(403)
            return fn(user, *a, **k)
        return wrapper
    return deco

@app.route("/users/<user>", methods=["DELETE"])
@require_role("admin")
def delete_user(user):
    USERS.remove(user)
    return "", 204

